def first_pos_2(a, target):
    left, right = 2, len(a) - 1
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] >= target:
            if a[mid] == target:
                result = mid
            right = mid - 1
        else:
            left = mid + 1
    return result

