def factorial(n):
    result = 1
    for k in range(2,n+1):
        result *= k
    return result

def fibonacci(n):
    a,b = 0,1
    for _ in range(n):
        a,b = b,a+b
    return a

def gcd(a, b):
    while b:
        a,b = b,a%b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    x,y = a,b
    while y:
        x,y = y,x%y
    return a//x*b

def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d*d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

def to_binary(n):
    if n == 0:
        return '0'
    bits = []
    while n:
        bits.append(str(n % 2)); n //= 2
    return ''.join(reversed(bits))

def from_binary(text):
    result = 0
    for ch in text:
        result = result*2 + (1 if ch == '1' else 0)
    return result

def popcount(n):
    count = 0
    while n:
        n &= n-1
        count += 1
    return count

def two_sum_exists(nums, target):
    seen = set()
    for x in nums:
        if target-x in seen:
            return True
        seen.add(x)
    return False

def max_subarray_sum(nums):
    if not nums:
        return None
    current = best = nums[0]
    for x in nums[1:]:
        current = max(x,current+x)
        best = max(best,current)
    return best

def longest_positive_run(nums):
    best = current = 0
    for x in nums:
        current = current+1 if x > 0 else 0
        best = max(best,current)
    return best

def missing_number(nums):
    n = len(nums)
    return n*(n+1)//2-sum(nums)

def majority(nums):
    if not nums:
        return None
    candidate = None
    count = 0
    for x in nums:
        if count == 0:
            candidate = x
        count += 1 if x == candidate else -1
    return candidate if nums.count(candidate) > len(nums)//2 else None

def dedup_adjacent(nums):
    result = []
    for x in nums:
        if not result or result[-1] != x:
            result.append(x)
    return result

def merge_intervals(intervals):
    result = []
    for left,right in sorted(intervals):
        if result and left <= result[-1][1]:
            result[-1][1] = max(result[-1][1],right)
        else:
            result.append([left,right])
    return result

def balanced_all(text):
    stack = []
    pairs = {')':'(',']':'[','}':'{'}
    for ch in text:
        if ch in '([{':
            stack.append(ch)
        elif not stack or stack.pop() != pairs[ch]:
            return False
    return not stack

def reachable(graph, start, target):
    seen = {start}
    stack = [start]
    while stack:
        node = stack.pop()
        if node == target:
            return True
        for nxt in graph.get(node,[]):
            if nxt not in seen:
                seen.add(nxt); stack.append(nxt)
    return False

def shortest_edges(graph, start, target):
    from collections import deque
    queue = deque([(start,0)])
    seen = {start}
    while queue:
        node,d = queue.popleft()
        if node == target:
            return d
        for nxt in graph.get(node,[]):
            if nxt not in seen:
                seen.add(nxt); queue.append((nxt,d+1))
    return -1

def stairs(n):
    a,b = 1,1
    for _ in range(n):
        a,b = b,a+b
    return a

def min_coins(coins, amount):
    dp = [0] + [amount+1]*amount
    for total in range(1,amount+1):
        for coin in coins:
            if coin <= total:
                dp[total] = min(dp[total],dp[total-coin]+1)
    return dp[amount] if dp[amount] <= amount else -1

def lis_length(nums):
    if not nums:
        return 0
    dp = [1]*len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i],dp[j]+1)
    return max(dp)

def binary_find(a, target):
    left, right = 0, len(a) - 1
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] >= target:
            if a[mid] == target:
                result = mid
            right = mid - 1
        else:
            left = mid + 1
    return result
